const MAX_CONCURRENT = 8
let active = 0, queue = []
function request(opts) {
  return new Promise((resolve, reject) => {
    queue.push({ opts, resolve, reject })
    dequeue()
  })
}
function dequeue() {
  if (active >= MAX_CONCURRENT || !queue.length) return
  active++
  const { opts, resolve, reject } = queue.shift()
  wx.request({...opts, complete: res => {
    active--; dequeue()
    res.statusCode < 300 ? resolve(res) : reject(res)
  }})
}

