class SocketManager {
  constructor() {
    this.task = null
    this.connected = false
  }
  connect(url) {
    if (this.connected) return
    this.task = wx.connectSocket({ url })
    this.task.onOpen(() => this.connected = true)
    this.task.onClose(() => this.connected = false)
  }
}

